contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 beforeBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeEth = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 afterBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterEth = address(c).balance;

        assert(
            reverted ||
            (afterBal == 0 && afterEth + beforeBal <= beforeEth && beforeEth == afterEth + beforeBal)
        );
    }

    receive() external payable {}
}

